import FischerCore

/// The result of matching one game against a CQL program.
public struct GameMatch: Sendable {
    public let gameNumber: Int
    /// Number of positions that matched the CQL body.
    public let matchCount: Int
    /// `positionid`s of the matched positions, in visiting order.
    public let matchedPositions: [Int]
    /// Comments generated by `comment`, `///` and friends.
    public let comments: [GeneratedComment]
    /// Best value of each `sort` filter (keyed by documentation string).
    public let sortValues: [(key: String, value: Value)]
    /// The game annotated with CQL comments, as PGN text.
    public let annotatedPGN: String
    public let game: GameTree
}

/// The outcome of running a CQL program over a PGN collection.
public struct CQLResult: Sendable {
    /// Matching games, in output order (sorted if the program sorts).
    public let matches: [GameMatch]
    /// Number of games examined.
    public let gamesExamined: Int
    /// Persistent variables at the end of the run (excluding `quiet` ones).
    public let persistentVariables: [(name: String, value: Value)]

    /// All matching games as one PGN document.
    public var outputPGN: String {
        matches.map(\.annotatedPGN).joined(separator: "\n\n") + (matches.isEmpty ? "" : "\n")
    }
}

/// Runs CQL programs over PGN games.
public final class CQLEngine {
    public struct Options: Sendable {
        /// Overrides the header's `variations` parameter.
        public var variations: Bool?
        public var gameNumber: ClosedRange<Int>?
        public var matchCount: ClosedRange<Int>?
        public var silent: Bool?
        public var quiet: Bool?
        public var matchString: String?
        /// Whether to add the "game number" header comment to matching games.
        public var headerComments = true

        public init() {}
    }

    public let program: CQLProgram
    public let options: Options
    public let evaluator: Evaluator
    private let sortKeys: [(key: String, minimum: Bool)]

    public init(program: CQLProgram, options: Options = Options()) throws(CQLError) {
        self.program = program
        self.options = options
        self.evaluator = try Evaluator(program: program, searchVariations: options.variations)
        var keys: [(String, Bool)] = []
        Self.collectSortKeys(evaluator.body, into: &keys)
        self.sortKeys = keys
    }

    /// Parses `source` and creates an engine for it.
    public convenience init(source: String, options: Options = Options()) throws(CQLError) {
        try self.init(program: try Parser.parse(source), options: options)
    }

    /// Runs the program over every game of a PGN document.
    public func run(pgn: String) throws(CQLError) -> CQLResult {
        try withLargeStack { () throws(CQLError) -> CQLResult in
            let games: [GameTree]
            do {
                games = try GameTree.games(fromPGN: pgn)
            } catch {
                throw CQLError(.input, "cannot read PGN: \(error)")
            }
            return try self.runGames(games)
        }
    }

    public func run(games: [GameTree]) throws(CQLError) -> CQLResult {
        try withLargeStack { () throws(CQLError) -> CQLResult in try self.runGames(games) }
    }

    private func runGames(_ games: [GameTree]) throws(CQLError) -> CQLResult {
        let header = program.header
        let gameRange = options.gameNumber ?? header.gameNumber
        let countRange = options.matchCount ?? header.matchCount
        evaluator.lastGameNumberValue = min(games.count, gameRange?.upperBound ?? games.count)
        var matches: [GameMatch] = []
        var examined = 0
        for game in games {
            if let gameRange, !gameRange.contains(game.gameNumber) { continue }
            if let result = header.result, game.tags["Result"] != result { continue }
            examined += 1
            if let match = try evaluateGame(game, countRange: countRange) { matches.append(match) }
        }
        if !sortKeys.isEmpty || header.sortByMatchCount {
            matches = sorted(matches)
        }
        let persistent = evaluator.persistentVariables
            .filter { !$0.value }
            .compactMap { name, _ in evaluator.variables[name].map { (name: name, value: $0) } }
            .sorted { $0.name < $1.name }
        return CQLResult(matches: matches, gamesExamined: examined, persistentVariables: persistent)
    }

    /// Matches a single game. Returns `nil` if the game does not match.
    public func evaluate(game: GameTree, countRange: ClosedRange<Int>? = nil) throws(CQLError) -> GameMatch? {
        try withLargeStack { () throws(CQLError) -> GameMatch? in try self.evaluateGame(game, countRange: countRange) }
    }

    private func evaluateGame(_ game: GameTree, countRange: ClosedRange<Int>?) throws(CQLError) -> GameMatch? {
        evaluator.begin(game: game)
        var matched: [PositionNode] = []
        for position in evaluator.visiblePositions where try evaluator.matches(at: position) {
            matched.append(position)
        }
        let range = countRange ?? options.matchCount ?? program.header.matchCount
        let isMatch = range.map { $0.contains(matched.count) } ?? !matched.isEmpty
        guard isMatch else { return nil }
        let sortValues = sortKeys.compactMap { key, _ in evaluator.sortValues[key].map { (key: key, value: $0.value) } }
        return GameMatch(gameNumber: game.gameNumber, matchCount: matched.count,
                         matchedPositions: matched.map(\.id), comments: evaluator.comments,
                         sortValues: sortValues,
                         annotatedPGN: annotate(game, matched: matched),
                         game: game)
    }

    // MARK: - Output

    private func annotate(_ tree: GameTree, matched: [PositionNode]) -> String {
        var game = tree.source
        let silent = options.silent ?? program.header.silent
        let quiet = options.quiet ?? program.header.quiet
        let matchString = options.matchString ?? program.header.matchString ?? "CQL"

        func add(_ text: String, at path: [Int]) {
            guard !text.isEmpty else { return }
            if path.isEmpty {
                game.tree.initialAnnotations.comments.append(text)
            } else {
                _ = game.tree.updateAnnotations(at: MovePath(path)) { $0.comments.append(text) }
            }
        }

        for id in evaluator.removedComments {
            guard let node = tree.nodes.first(where: { $0.id == id }) else { continue }
            if node.path.isEmpty {
                game.tree.initialAnnotations.comments = []
            } else {
                _ = game.tree.updateAnnotations(at: MovePath(node.path)) { $0.comments = [] }
            }
        }
        for (name, value) in evaluator.tagEdits {
            if let tag = PGNTag(rawValue: name) {
                if game.tags[tag] == nil { game.tagOrder.append(tag) }
                game.tags[tag] = value
            }
        }

        if !silent {
            if options.headerComments {
                var header = "Game number \(tree.gameNumber)"
                for (key, value) in sortKeys.compactMap({ key, _ in evaluator.sortValues[key].map { (key, $0) } }) {
                    header += "; \(value.documentation ?? "sort") \(value.value)"
                    _ = key
                }
                add(header, at: [])
            }
            for comment in evaluator.comments { add(comment.text, at: comment.path) }
            if !quiet {
                for node in matched { add(matchString, at: node.path) }
            }
        }
        return game.pgn()
    }

    // MARK: - Sorting

    private static func collectSortKeys(_ filter: Filter, into keys: inout [(String, Bool)]) {
        if case .sort(let minimum, _, let documentation, let inner) = filter {
            let key = documentation ?? "\(inner.hashValue)"
            if !keys.contains(where: { $0.0 == key }) { keys.append((key, minimum)) }
        }
        _ = try? filter.mapChildren { child in
            collectSortKeys(child, into: &keys)
            return child
        }
    }

    private func sorted(_ matches: [GameMatch]) -> [GameMatch] {
        let indexed = Array(matches.enumerated())
        return indexed.sorted { lhs, rhs in
            if program.header.sortByMatchCount, lhs.element.matchCount != rhs.element.matchCount {
                return lhs.element.matchCount > rhs.element.matchCount
            }
            for (key, minimum) in sortKeys {
                let a = lhs.element.sortValues.first { $0.key == key }?.value
                let b = rhs.element.sortValues.first { $0.key == key }?.value
                switch (a, b) {
                case (nil, nil): continue
                case (nil, _): return false
                case (_, nil): return true
                case (let a?, let b?):
                    let order = Evaluator.compare(a, b)
                    if order != 0 { return minimum ? order < 0 : order > 0 }
                }
            }
            return lhs.offset < rhs.offset
        }.map(\.element)
    }
}
